 AND (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=ANY(ARRAY['horse_publication_private.reusable_confirmation','public.get_my_horse_offer_publication_snapshot_v1','public.prepare_my_horse_publication_v1','public.publish_my_horse_offer_v1']::text[]))=3 AS capability_absent,
 capability='36f85275e0bdf86673466084a69a67d47cd92677821b87d2555663a24b34a8b2' AND (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname||'.'||p.proname=ANY(ARRAY['horse_publication_private.reusable_confirmation','public.get_my_horse_offer_publication_snapshot_v1','public.prepare_my_horse_publication_v1','public.publish_my_horse_offer_v1']::text[]))=4 AS capability_present FROM measured),
 assessed AS (SELECT *,coalesce(functions AND installer AND actor_roles AND closed_private_schema AND core_relations
 AND required_columns AND managed_triggers AND final_writer_policies AND hosted_context_ready,false) dependencies_ok FROM checks),
 result_row AS (SELECT jsonb_build_object('schema_version',1,'kind','horse-confirmation-reuse-v1',
 'state',CASE WHEN dependencies_ok AND capability_absent AND NOT capability_present THEN 'absent'
 WHEN dependencies_ok AND capability_present AND NOT capability_absent THEN 'applied' ELSE 'unknown' END,
 'recognized',dependencies_ok AND (capability_absent<>capability_present),'ready_to_apply',dependencies_ok AND capability_absent AND NOT capability_present,
 'dependencies_ok',dependencies_ok,'capability_absent',capability_absent,'capability_present',capability_present,
