hoto_upload_v2','public.get_listing_multipart_v2','public.get_my_horse_media_binding_v1','public.get_my_horse_offer_edit_snapshot_v1','public.get_my_horse_offer_lifecycle_v1','public.get_my_horse_offer_v1','public.get_my_horse_publication_attempt_v1','public.get_my_horse_publication_image_binding_v1','public.get_my_listing_cleanup_summary_v1','public.get_my_listing_conversation_v1','public.get_my_listing_conversation_v2','public.get_my_listing_media_binding_v2','public.get_my_listing_publication_confirmation_v1','public.get_my_listing_publication_journey_v2','public.get_my_listing_publication_v1','public.get_my_listing_retired_web_cleanup_v1','public.get_my_managed_listing_image_addition_v1','public.get_my_managed_listing_images_v1','public.get_my_managed_listing_v2','public.get_my_marketplace_message_thread_v1','public.get_my_message_photo_binding_v2','public.get_my_message_thread_v2','public.get_public_horse_media_binding_v1','public.get_public_horse_offer_v1','public.get_public_listing_media_binding_v1','public.get_required_publication_policies_v1','public.get_selqiro_hosted_preview_readiness_v1','public.guard_listing_price_v2','public.hide_my_thread_v2','public.list_my_listing_conversations_v1','public.list_my_message_threads_v2','public.listing_actor_uid_hosted_v1','public.listing_basics_search_text_v1','public.listing_contact_is_managed_v1','public.listing_contact_visible_v1','public.listing_create_category_path_valid_v1','public.listing_final_guard_state_v1','public.listing_price_currency_scale_v1','public.listing_price_legacy_label_v1','public.listing_price_read_model_v1','public.listing_price_tuple_valid_v1','public.lock_listing_creation_actor_v1','public.mark_my_thread_read_v2','public.normalize_listing_basics_v1','public.normalize_listing_create_location_v1','public.normalize_listing_creation_v1','public.normalize_listing_price_v1','public.prepare_listing_multipart_cleanup_v2','public.prepare_listing_web_write_v1','public.prepare_my_listing_publication_v1','public.prepare_my_managed_listing_image_addition_v1','public.prevent_horse_offer_publication_event_update_v1','public.prevent_publication_policy_acceptance_update','public.prevent_publication_policy_document_version_mutation','public.public_listing_search_document_v1','public.publish_my_listing_v1','public.record_horse_publication_cleanup_v1','public.record_listing_account_source_cleanup_v1','public.record_listing_cleanup_v1','public.record_listing_multipart_abort_v2','public.record_listing_multipart_completed_v2','public.record_listing_multipart_created_v2','public.record_listing_multipart_verified_v2','public.record_listing_published_source_cleanup_v1','public.record_listing_retired_web_cleanup_v1','public.record_listing_web_ready_v1','public.remove_my_managed_listing_image_v1','public.renew_my_horse_offer_activity_v1','public.require_listing_create_keys_v1','public.require_my_active_identity_v2','public.require_my_current_publication_policy_acceptance_v1','public.reserve_listing_multipart_v2','public.reserve_my_message_photo_v2','public.search_public_marketplace_v1','public.send_my_listing_message_v1','public.send_my_message_v2','public.set_listing_primary_image_v2','public.set_my_horse_offer_status_v1','public.set_my_managed_listing_primary_image_v1','public.set_my_thread_block_v2','public.set_publication_policy_acceptance_snapshot','public.set_v2_profile_content_updated_at','public.update_horse_offer_search_vector_v1','public.update_my_horse_offer_draft_v1','public.validate_horse_offer_current_publication_event_v1','public.validate_horse_offer_image_identity_v1','public.validate_horse_offer_publication_event_v1','horse_publication_private.reusable_confirmation','public.get_my_horse_offer_publication_snapshot_v1','public.prepare_my_horse_publication_v1','public.publish_my_horse_offer_v1']::text[]))),relation_facts AS (SELECT n.nspname||'.'||c.relname name,
 jsonb_build_object('name',n.nspname||'.'||c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),
 'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'persistence',c.relpersistence,
 'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
  'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(ad.adbin,ad.adrelid),
  'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END) ORDER BY a.attnum),'[]')
  FROM pg_attribute a LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum
  WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',q.conname,'type',q.contype,'definition',pg_get_constraintdef(q.oid),
  'validated',q.convalidated,'deferrable',q.condeferrable,'deferred',q.condeferred,'local',q.conislocal,'inheritance',q.coninhcount,
  'no_inherit',q.connoinherit) ORDER BY q.conname),'[]') FROM pg_constraint q WHERE q.conrelid=c.oid AND q.contype<>'n'),
 'nonstandard_not_null',(SELECT count(*) FROM pg_constraint q WHERE q.conrelid=c.oid AND q.contype='n'
  AND (NOT q.convalidated OR NOT q.conislocal OR q.coninhcount<>0 OR q.connoinherit)),
 'inheritance',(SELECT coalesce(jsonb_agg(i.inhparent::regclass::text ORDER BY i.inhseqno),'[]') FROM pg_inherits i WHERE i.inhrelid=c.oid),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),
  'valid',i.indisvalid,'ready',i.indisready) ORDER BY ic.relname),'[]') FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))
  ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND NOT false)) structure,
 jsonb_build_object('acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),
  'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)
  ORDER BY x.grantee::regrole::text,x.privilege_type,x.is_grantable),'[]') FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),
 'column_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('column',a.attname,'grantor',pg_get_userbyid(x.grantor),
  'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)
  ORDER BY a.attname,x.grantee::regrole::text,x.privilege_type),'[]') FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x
  WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',q.polname,'permissive',q.polpermissive,'command',q.polcmd,
  'roles',(SELECT jsonb_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END ORDER BY r::regrole::text) FROM unnest(q.polroles) r),
  'using',pg_get_expr(q.polqual,q.polrelid),'check',pg_get_expr(q.polwithcheck,q.polrelid)) ORDER BY q.polname),'[]')
  FROM pg_policy q WHERE q.polrelid=c.oid)) authority
